require_once __DIR__ . "/../config/database.php";
function postv($n,$d=''){return isset($_POST[$n])&&!is_array($_POST[$n])?trim((string)$_POST[$n]):$d;}
function uploadImage($field,$prefix){if(!isset($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']<=0||$f['size']>2*1024*1024)throw new RuntimeException('Invalid upload for '.$prefix.'.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'];if(!isset($allowed[$mime])||@getimagesize($f['tmp_name'])===false)throw new RuntimeException($prefix.' must be a PNG, JPG or WebP image.');$dir=__DIR__.'/uploads/'.($prefix==='stamp'?'stamps':'signatures');if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Unable to create upload directory.');$name=$prefix.'_'.bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new RuntimeException('Unable to save upload.');return 'uploads/'.($prefix==='stamp'?'stamps':'signatures').'/'.$name;}
try{
