$pdo->exec("CREATE TABLE IF NOT EXISTS valve_pressure_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, valve_id INT UNSIGNED NOT NULL, description VARCHAR(255) NOT NULL, cavity_body_test VARCHAR(255) NULL, seat_test VARCHAR(255) NULL, remarks VARCHAR(255) NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(valve_id), CONSTRAINT fk_valve_pressure_log_valve FOREIGN KEY(valve_id) REFERENCES valve_certificates(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS valve_physical_checks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, valve_id INT UNSIGNED NOT NULL, check_left VARCHAR(255) NULL, result_left VARCHAR(100) NULL, check_right VARCHAR(255) NULL, result_right VARCHAR(100) NULL, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(valve_id), CONSTRAINT fk_valve_physical_valve FOREIGN KEY(valve_id) REFERENCES valve_certificates(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS nuprc_settings (id INT UNSIGNED PRIMARY KEY, nuprc VARCHAR(255) NOT NULL DEFAULT '', updated_by INT UNSIGNED NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$pdo->exec("INSERT INTO nuprc_settings (id,nuprc) VALUES (1,'') ON DUPLICATE KEY UPDATE id=id");$nuprc=(string)($pdo->query("SELECT nuprc FROM nuprc_settings WHERE id=1")->fetchColumn()?:'');
$no=postv('certificate_no');$client=postv('client');if($no==='')throw new RuntimeException('Certificate number is required.');if($client==='')throw new RuntimeException('Client is required.');
$dups=$pdo->prepare("SELECT id FROM valve_certificates WHERE certificate_no=:n LIMIT 1");$dups->execute([':n'=>$no]);if($dups->fetchColumn()!==false)throw new RuntimeException('CERTIFICATE NUMBER ALREADY USED: '.$no);
foreach([['gauge_calibrations','Gauge'],['recorder_calibrations','Recorder']] as $pair){try{$exists=$pdo->query("SHOW TABLES LIKE '{$pair[0]}'")->fetchColumn();if($exists){$q=$pdo->prepare("SELECT id FROM {$pair[0]} WHERE certificate_no=:n LIMIT 1");$q->execute([':n'=>$no]);if($q->fetchColumn()!==false)throw new RuntimeException('CERTIFICATE NUMBER ALREADY USED BY '.$pair[1].': '.$no);}}catch(PDOException $ignore){}}
$testedSig=uploadImage('tested_signature','tested');$witnessedSig=uploadImage('witnessed_signature','witnessed');$stamp=uploadImage('stamp_image','stamp');
$stmt=$pdo->prepare("INSERT INTO valve_certificates (certificate_no,client,nuprc,test_location,tested_item,valve_class,serial_no,matp,test_date,body_test_date,seat_test_date,body_total_time,seat_total_time,body_medium,seat_medium,body_final_pressure,seat_final_pressure,tested_by,tested_name,witnessed_by,tested_signature,witnessed_signature,stamp_image,created_by) VALUES (:no,:client,:nuprc,:loc,:item,:class,:serial,:matp,:td,:bd,:sd,:btime,:stime,:bm,:sm,:bfp,:sfp,:tb,:tn,:wb,:ts,:ws,:stamp,:uid)");$stmt->execute([':no'=>$no,':client'=>$client,':nuprc'=>$nuprc,':loc'=>postv('test_location'),':item'=>postv('tested_item'),':class'=>postv('valve_class'),':serial'=>postv('serial_no'),':matp'=>postv('matp'),':td'=>postv('test_date')?:null,':bd'=>postv('body_test_date')?:null,':sd'=>postv('seat_test_date')?:null,':btime'=>postv('body_total_time'),':stime'=>postv('seat_total_time'),':bm'=>postv('body_medium'),':sm'=>postv('seat_medium'),':bfp'=>postv('body_final_pressure'),':sfp'=>postv('seat_final_pressure'),':tb'=>postv('tested_by'),':tn'=>postv('tested_name'),':wb'=>postv('witnessed_by'),':ts'=>$testedSig,':ws'=>$witnessedSig,':stamp'=>$stamp,':uid'=>(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();
$descs=$_POST['description']??[];$bodies=$_POST['body_log']??[];$seats=$_POST['seat_log']??[];$remarks=$_POST['remarks']??[];$ins=$pdo->prepare("INSERT INTO valve_pressure_log (valve_id,description,cavity_body_test,seat_test,remarks,sort_order) VALUES (:vid,:d,:b,:s,:r,:o)");foreach($descs as $i=>$d){$d=trim((string)$d);if($d==='')continue;$ins->execute([':vid'=>$id,':d'=>$d,':b'=>trim((string)($bodies[$i]??'')),':s'=>trim((string)($seats[$i]??'')),':r'=>trim((string)($remarks[$i]??'')),':o'=>$i]);}
$cl=$_POST['check_left']??[];$rl=$_POST['result_left']??[];$cr=$_POST['check_right']??[];$rr=$_POST['result_right']??[];$pin=$pdo->prepare("INSERT INTO valve_physical_checks (valve_id,check_left,result_left,check_right,result_right,sort_order) VALUES (:v,:cl,:rl,:cr,:rr,:o)");foreach($cl as $i=>$v){$pin->execute([':v'=>$id,':cl'=>trim((string)$v),':rl'=>trim((string)($rl[$i]??'')),':cr'=>trim((string)($cr[$i]??'')),':rr'=>trim((string)($rr[$i]??'')),':o'=>$i]);}
header('Location: valve-certificate.php?id='.$id);exit;
